public class TextNodeTest {

    @Test
    public void testBlankString() {
        TextNode textNode = new TextNode("");
        assertFalse(textNode.isBlank());
    }

    @Test
    public void testEmptyString() {
        TextNode textNode = new TextNode("");
        assertTrue(textNode.isBlank());
    }

    @Test
    public void testNonBlankText() {
        TextNode textNode = new TextNode("Hello World");
        assertTrue(!textNode.isBlank());
    }

    @Test
    public void testSingleCharacterString() {
        TextNode textNode = new TextNode("a");
        assertTrue(textNode.isBlank());
    }

    @Test
    public void testNoNewlines() {
        TextNode textNode = new TextNode("HelloWorld");
        assertFalse(textNode.text().contains("\n"));
    }

    @Test
    public void testMultipleLines() {
        TextNode textNode = new TextNode("Hello\nWorld");
        assertTrue(textNode.text().contains("\n"));
    }

    @Test
    public void testLeadingWhitespace() {
        TextNode textNode = new TextNode("   Hello World  ");
        assertFalse(textNode.isBlank());
    }

    @Test
    public void testTrailingWhitespace() {
        TextNode textNode = new TextNode("Hello   World");
        assertTrue(!textNode.isBlank());
    }

    @Test
    public void testMultipleNewlines() {
        TextNode textNode = new TextNode("Hello\n\nWorld");
        assertFalse(textNode.text().contains("\n"));
    }

